import{_ as n,C as o,o as r,c as t,j as i,E as l,a as e,a2 as h}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/9-sinf-game/"},"n":2,"bob":"I-bob · Game Design asoslari","lessons":[{"g":4,"title":"O‘yin loyihalash va ssenariy: G'oyadan voqealar zanjirigacha","lead":"Kitobda siz hikoyani o'qiysiz, kinoda uni ko'rasiz, o'yinda esa siz ushbu hikoyaning ichida yashaysiz va uni o'zingiz yaratasiz!","link":"/9-sinf-game/hafta-02/dars-1","slide":"/slaydlar/9-sinf-game/hafta-02/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-1-test.html"},{"g":5,"title":"Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","lead":"2D o'yin san'ati — bu har bir piksel va chiziq orqali virtual dunyoni jonlantirish, o'yinchiga estetik zavq va unutilmas vizual muhit ulashish mahoratidir!","link":"/9-sinf-game/hafta-02/dars-2","slide":"/slaydlar/9-sinf-game/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-2-test.html"},{"g":6,"title":"Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, qatlamlar va uskunalar","lead":"Professional grafik dizayner hech qachon rasmni buzib o'chirmaydi. U niqoblar (maskalar) va qatlamlar orqali sehrli o'zgarishlar yaratadi!","link":"/9-sinf-game/hafta-02/dars-3","slide":"/slaydlar/9-sinf-game/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-game/hafta-02/index.md","filePath":"9-sinf-game/hafta-02/index.md"}`),d={name:"9-sinf-game/hafta-02/index.md"},g={class:"blk"},y={id:"uyga-vazifa",tabindex:"-1"};function m(u,a,f,v,q,c){const s=o("Icon");return r(),t("div",null,[i("div",g,[i("h2",y,[l(s,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=h('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_4-dars-o-yin-loyihalash-va-ssenariy-high-concept-hikoya-turlari-va-gdd" tabindex="-1">4-dars: O‘yin loyihalash va ssenariy: High Concept, hikoya turlari va GDD <a class="header-anchor" href="#_4-dars-o-yin-loyihalash-va-ssenariy-high-concept-hikoya-turlari-va-gdd" aria-label="Permalink to &quot;4-dars: O‘yin loyihalash va ssenariy: High Concept, hikoya turlari va GDD&quot;">​</a></h3><ol><li>O&#39;zingiz orzu qilgan 2D o&#39;yin uchun 2–3 ta jumlada lo&#39;nda va jozibador <strong>High Concept</strong> yozing.</li><li>Qahramoningiz sayohatini Jozef Kempbellning &quot;Qahramon sayohati&quot; (Hero&#39;s Journey) modelining kamida 4 ta bosqichi (Oddiy olam, Chaqiriq, Sinovlar, G&#39;alaba) orqali yoritib bering.</li><li>O&#39;yiningiz ssenariysi qaysi turga mansubligini (Chiziqli, Tarmoqlanuvchi yoki Ochiq olam) belgilang va o&#39;yinchining bitta qarori voqealar rivojiga qanday ta&#39;sir qilishini tasvirlang.</li><li>O&#39;yin sahnasiga dialoglarsiz voqeani tushuntiruvchi bitta atrof-muhit detali (<strong>Environmental Storytelling</strong>) o&#39;ylab toping (masalan, kimsasiz xonada yoniq qolgan kompyuter yoki singan qalqon).</li></ol><hr><h3 id="_5-dars-photoshop-interfeysi-va-vositalari-1-qism-2d-grafika-spraytlar-va-canvas" tabindex="-1">5-dars: Photoshop interfeysi va vositalari (1-qism): 2D grafika, spraytlar va Canvas <a class="header-anchor" href="#_5-dars-photoshop-interfeysi-va-vositalari-1-qism-2d-grafika-spraytlar-va-canvas" aria-label="Permalink to &quot;5-dars: Photoshop interfeysi va vositalari (1-qism): 2D grafika, spraytlar va Canvas&quot;">​</a></h3><ol><li>O&#39;yin grafikasida nima uchun 32x32 yoki 64x64 pikselli <strong>Tayllar (Tiles)</strong> va <strong>Spraytlar (Sprites)</strong> ishlatilishini, ularning o&#39;yin xotirasi (RAM)ga ta&#39;sirini tushuntiring.</li><li>3 ta chuqurlik qatlamidan iborat <strong>Parallaks foni (Parallax Scrolling)</strong> ssenariysini tuzing (osmon, uzoq tog&#39;lar, oldingi o&#39;rmon) va qaysi biri qanday tezlikda harakatlanishini yozing.</li><li>Photoshopda 2D mobil platformer o&#39;yini uchun yangi hujjat ochish parametrlarini aniqlang: Canvas o&#39;lchami (Width/Height px), Resolution (DPI), Color Mode va Background Contents.</li><li>Rastrli grafikaning 2 ta kamchiligini va Vektorli grafikaning 2 ta ustunligini o&#39;yin dizayni nuqtai nazaridan sanab o&#39;ting.</li></ol><hr><h3 id="_6-dars-photoshop-interfeysi-va-vositalari-2-qism-tanlash-vositalari-layer-masks-va-blending-modes" tabindex="-1">6-dars: Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, Layer Masks va Blending Modes <a class="header-anchor" href="#_6-dars-photoshop-interfeysi-va-vositalari-2-qism-tanlash-vositalari-layer-masks-va-blending-modes" aria-label="Permalink to &quot;6-dars: Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, Layer Masks va Blending Modes&quot;">​</a></h3><ol><li>Bir xil rangdagi oq fonda joylashgan o&#39;yin assetini ajratib olib, yangi shaffof qatlamga o&#39;tkazishning 3 ta qadamini ketma-ket yozing (asboblar va klaviatura tugmalari bilan).</li><li>Professional o&#39;yin artistlari nima uchun o&#39;chirg&#39;ich (Eraser Tool) o&#39;rniga <strong>Layer Mask (Qatlam niqobi)</strong> ishlatishini, uning oq va qora ranglari qanday ishlashini tushuntiring.</li><li>Qora fonga ega bo&#39;lgan alanga (olov) rasmidagi qora fonni yo&#39;qotib, faqat porlovchi olovni qahramonning qo&#39;liga tutqazish uchun qaysi <strong>Blending Mode</strong> qo&#39;llanilishini va bu rejim qanday ishlashini yozing.</li><li>Mo&#39;yqalam (Brush Tool) bilan ishlaganda o&#39;tkir qirrali sprayt chizish va tumanli sehrli nur taratish uchun <strong>Hardness</strong> parametri qanday qiymatlarga qo&#39;yilishini ayting.</li></ol><hr>',11))])])}const b=n(d,[["render",m]]);export{p as __pageData,b as default};
